key.query:
query GetAllPostsWithTotal($size: Int!, $offset: Int!) {
  posts(
    where: {offsetPagination: {size: $size, offset: $offset}, orderby: {field: DATE, order: DESC}}
  ) {
    pageInfo {
      offsetPagination {
        total
        __typename
      }
      __typename
    }
    nodes {
      databaseId
      slug
      title(format: RENDERED)
      excerpt(format: RENDERED)
      featuredImage {
        node {
          sourceUrl
          mediaDetails {
            sizes {
              name
              sourceUrl
              __typename
            }
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}
